//! Ordinary Rust APIs adapted to Rust bindings generated by upstream wit-bindgen.
use super::*;
use heck::{ToSnakeCase, ToUpperCamelCase};
use wit_parser::{FunctionKind, Type, TypeDefKind, TypeOwner};

fn identifier(name: &str, upper: bool) -> String {
    let name = if upper {
        name.to_upper_camel_case()
    } else {
        name.to_snake_case()
    };
    if matches!(
        name.as_str(),
        "as" | "async"
            | "await"
            | "break"
            | "const"
            | "continue"
            | "crate"
            | "dyn"
            | "else"
            | "enum"
            | "extern"
            | "false"
            | "fn"
            | "for"
            | "if"
            | "impl"
            | "in"
            | "let"
            | "loop"
            | "match"
            | "mod"
            | "move"
            | "mut"
            | "pub"
            | "ref"
            | "return"
            | "self"
            | "Self"
            | "static"
            | "struct"
            | "super"
            | "trait"
            | "true"
            | "type"
            | "unsafe"
            | "use"
            | "where"
            | "while"
            | "yield"
            | "try"
            | "gen"
            | "abstract"
            | "become"
            | "box"
            | "do"
            | "final"
            | "macro"
            | "override"
            | "priv"
            | "typeof"
            | "unsized"
            | "virtual"
    ) {
        format!("{name}_")
    } else {
        name
    }
}

fn scope(resolve: &Resolve, id: wit_parser::InterfaceId) -> Result<String> {
    let interface = &resolve.interfaces[id];
    let package = &resolve.packages[interface
        .package
        .context("inferred Rust interface package")?]
    .name;
    Ok(format!(
        "exports::{}::{}::{}",
        identifier(&package.namespace, false),
        identifier(&package.name, false),
        identifier(
            interface
                .name
                .as_deref()
                .context("inferred Rust interface name")?,
            false
        )
    ))
}

fn wire_type(resolve: &Resolve, ty: Type) -> Result<String> {
    Ok(match ty {
        Type::Bool => "bool".into(),
        Type::U8 => "u8".into(),
        Type::U16 => "u16".into(),
        Type::U32 => "u32".into(),
        Type::U64 => "u64".into(),
        Type::S8 => "i8".into(),
        Type::S16 => "i16".into(),
        Type::S32 => "i32".into(),
        Type::S64 => "i64".into(),
        Type::F32 => "f32".into(),
        Type::F64 => "f64".into(),
        Type::String => "String".into(),
        Type::Id(id) => {
            let definition = &resolve.types[id];
            if let Some(name) = &definition.name {
                let prefix = match definition.owner {
                    TypeOwner::Interface(id) => format!("{}::", scope(resolve, id)?),
                    TypeOwner::World(_) | TypeOwner::None => String::new(),
                };
                return Ok(format!("{prefix}{}", identifier(name, true)));
            }
            match &definition.kind {
                TypeDefKind::Type(ty) => wire_type(resolve, *ty)?,
                TypeDefKind::List(ty) => format!("Vec<{}>", wire_type(resolve, *ty)?),
                TypeDefKind::Option(ty) => format!("Option<{}>", wire_type(resolve, *ty)?),
                TypeDefKind::Result(result) => format!(
                    "Result<{}, {}>",
                    result
                        .ok
                        .map(|ty| wire_type(resolve, ty))
                        .transpose()?
                        .unwrap_or_else(|| "()".into()),
                    result
                        .err
                        .map(|ty| wire_type(resolve, ty))
                        .transpose()?
                        .unwrap_or_else(|| "()".into())
                ),
                _ => bail!("unsupported anonymous inferred Rust WIT type"),
            }
        }
        _ => bail!("unsupported inferred Rust WIT type"),
    })
}

struct Bridge<'a> {
    resolve: &'a Resolve,
    next: usize,
}
impl Bridge<'_> {
    fn payload(
        &mut self,
        wire: Option<Type>,
        source: Option<&SourceType>,
        to_native: bool,
        value: &str,
    ) -> Result<String> {
        match (wire, source) {
            (Some(wire), Some(source)) => self.convert(wire, source, to_native, value),
            (None, None) => Ok("()".into()),
            _ => bail!("inferred Rust result payload differs from WIT"),
        }
    }
    fn convert(
        &mut self,
        wire: Type,
        source: &SourceType,
        to_native: bool,
        value: &str,
    ) -> Result<String> {
        let resolve = self.resolve;
        ensure!(
            self.next < 16384,
            "inferred Rust conversion expansion limit"
        );
        let local = format!("__wisp_value_{}", self.next);
        self.next += 1;
        let generated = wire_type(resolve, wire)?;
        let (input, output) = if to_native {
            (generated.as_str(), source.name.as_str())
        } else {
            (source.name.as_str(), generated.as_str())
        };
        let body = match (wire, &source.kind) {
            (Type::Id(id), _) if matches!(resolve.types[id].kind, TypeDefKind::Type(_)) => {
                let TypeDefKind::Type(ty) = resolve.types[id].kind else {
                    unreachable!()
                };
                self.convert(ty, source, to_native, &local)?
            }
            (Type::Bool, SourceKind::Scalar) => local.clone(),
            (
                Type::U8
                | Type::U16
                | Type::U32
                | Type::U64
                | Type::S8
                | Type::S16
                | Type::S32
                | Type::S64
                | Type::F32
                | Type::F64,
                SourceKind::Scalar,
            ) => format!("({local} as {output})"),
            (Type::String, SourceKind::String) => local.clone(),
            (Type::Id(id), SourceKind::Bytes)
                if matches!(resolve.types[id].kind, TypeDefKind::List(Type::U8)) =>
            {
                local.clone()
            }
            (Type::Id(id), SourceKind::Record(fields)) => {
                let TypeDefKind::Record(record) = &resolve.types[id].kind else {
                    bail!("inferred Rust record differs from WIT")
                };
                ensure!(
                    fields.len() == record.fields.len(),
                    "inferred Rust record fields differ from WIT"
                );
                let mut members = Vec::new();
                for field in &record.fields {
                    let native = fields
                        .iter()
                        .find(|source| source.wire == field.name)
                        .context("inferred Rust record field")?;
                    let generated_name = identifier(&field.name, false);
                    let (input_name, output_name) = if to_native {
                        (generated_name.as_str(), native.name.as_str())
                    } else {
                        (native.name.as_str(), generated_name.as_str())
                    };
                    let converted = self.convert(
                        field.ty,
                        &native.ty,
                        to_native,
                        &format!("{local}.{input_name}"),
                    )?;
                    members.push(format!("{output_name}: {converted}"));
                }
                format!("{output} {{ {} }}", members.join(", "))
            }
            (Type::Id(id), SourceKind::List(element)) => {
                let TypeDefKind::List(ty) = resolve.types[id].kind else {
                    bail!("inferred Rust list differs from WIT")
                };
                let converted = self.convert(ty, element, to_native, "item")?;
                format!("{local}.into_iter().map(|item| {converted}).collect::<{output}>()")
            }
            (Type::Id(id), SourceKind::Option(element)) => {
                let TypeDefKind::Option(ty) = resolve.types[id].kind else {
                    bail!("inferred Rust option differs from WIT")
                };
                let converted = self.convert(ty, element, to_native, "item")?;
                format!("{local}.map(|item| {converted})")
            }
            (Type::Id(id), SourceKind::Enum(cases)) => {
                let TypeDefKind::Enum(enumeration) = &resolve.types[id].kind else {
                    bail!("inferred Rust enum differs from WIT")
                };
                ensure!(
                    cases.len() == enumeration.cases.len(),
                    "inferred Rust enum cases differ from WIT"
                );
                let mut arms = Vec::new();
                for case in &enumeration.cases {
                    let native = cases
                        .iter()
                        .find(|source| source.wire == case.name)
                        .context("inferred Rust enum case")?;
                    let generated = format!("{generated}::{}", identifier(&case.name, true));
                    let (from, to) = if to_native {
                        (generated.as_str(), native.name.as_str())
                    } else {
                        (native.name.as_str(), generated.as_str())
                    };
                    arms.push(format!("{from} => {to}"));
                }
                format!("match {local} {{ {} }}", arms.join(", "))
            }
            (Type::Id(id), SourceKind::Result { ok, err }) => {
                let TypeDefKind::Result(result) = &resolve.types[id].kind else {
                    bail!("inferred Rust result differs from WIT")
                };
                let success = self.payload(result.ok, ok.as_deref(), to_native, "value")?;
                let failure = self.payload(result.err, err.as_deref(), to_native, "value")?;
                format!(
                    "match {local} {{ Ok(value) => Ok({success}), Err(value) => Err({failure}) }}"
                )
            }
            _ => bail!(
                "unsupported inferred Rust source/WIT conversion: {}",
                source.name
            ),
        };
        Ok(format!("{{ let {local}: {input} = {value}; {body} }}"))
    }

    fn implementation(
        &mut self,
        functions: &[&wit_parser::Function],
        native: &BTreeMap<String, Function>,
        trait_path: &str,
    ) -> Result<String> {
        let mut output = format!("impl {trait_path} for __WispApplication {{\n");
        for function in functions {
            ensure!(
                matches!(function.kind, FunctionKind::Freestanding),
                "inferred Rust exports require synchronous free functions"
            );
            let source = native
                .get(&function.name)
                .with_context(|| format!("missing inferred Rust function {}", function.name))?;
            ensure!(
                source.source_params.len() == function.params.len(),
                "inferred Rust function parameters differ from WIT"
            );
            let mut parameters = Vec::new();
            let mut arguments = Vec::new();
            for (index, (parameter, source)) in function
                .params
                .iter()
                .zip(&source.source_params)
                .enumerate()
            {
                parameters.push(format!(
                    "a{index}: {}",
                    wire_type(self.resolve, parameter.ty)?
                ));
                arguments.push(self.convert(parameter.ty, source, true, &format!("a{index}"))?);
            }
            let call = format!(
                "__wisp_application::{}({})",
                source.original,
                arguments.join(", ")
            );
            let body =
                self.payload(function.result, source.source_result.as_ref(), false, &call)?;
            let body = if function.result.is_none() {
                format!("{call}; ()")
            } else {
                body
            };
            let result = function
                .result
                .map(|ty| wire_type(self.resolve, ty))
                .transpose()?
                .unwrap_or_else(|| "()".into());
            output.push_str(&format!(
                "fn {}({}) -> {result} {{ {body} }}\n",
                identifier(&function.name, false),
                parameters.join(", ")
            ));
        }
        output.push_str("}\n");
        Ok(output)
    }
}

pub(in crate::build) fn rust(
    resolve: &Resolve,
    world: WorldId,
    functions: &BTreeMap<String, Function>,
    library: &str,
) -> Result<String> {
    let mut exports = resolve.clone();
    // Imported component guest crates carry their own import sections. The
    // wrapper implements only the application's inferred exports.
    exports.worlds[world]
        .imports
        .retain(|_, item| matches!(item, WorldItem::Type { .. }));
    let generated = crate::generator_tools::wit_bindgen(
        &exports,
        world,
        "rust",
        &[
            "--runtime-path",
            "crate::__wisp_rt",
            "--ownership",
            "owning",
            "--generate-all",
        ],
    )?;
    ensure!(
        generated.len() == 1,
        "upstream inferred Rust bindings must produce one source file"
    );
    let (name, generated) = generated
        .into_iter()
        .next()
        .context("upstream inferred Rust bindings")?;
    ensure!(
        name.ends_with(".rs"),
        "upstream inferred Rust source missing"
    );
    let mut bridge = Bridge {
        resolve: &exports,
        next: 0,
    };
    let mut implementations = String::new();
    let mut root = Vec::new();
    let mut count = 0;
    for item in exports.worlds[world].exports.values() {
        match item {
            WorldItem::Interface { id, .. } => {
                let methods = exports.interfaces[*id]
                    .functions
                    .values()
                    .collect::<Vec<_>>();
                count += methods.len();
                implementations.push_str(&bridge.implementation(
                    &methods,
                    functions,
                    &format!("{}::Guest", scope(&exports, *id)?),
                )?);
            }
            WorldItem::Function(function) => {
                count += 1;
                root.push(function);
            }
            WorldItem::Type { .. } => {}
        }
    }
    if !root.is_empty() {
        implementations.push_str(&bridge.implementation(&root, functions, "Guest")?);
    }
    ensure!(
        count == functions.len(),
        "inferred Rust source functions differ from WIT exports"
    );
    Ok(format!(
        "extern crate {library} as __wisp_application;\nmod __wisp_rt {{\n{}\n}}\n{}\nstruct __WispApplication;\n{implementations}\nexport!(__WispApplication);\n",
        include_str!("../assets/upstream-wit-runtime.rs"),
        String::from_utf8(generated)?
    ))
}
